   375	    keyManager.SetMleFrameCounter(networkInfo.mMleFrameCounter);
   376	    keyManager.SetMacFrameCounter(networkInfo.mMacFrameCounter);
   377	
   378	    switch (networkInfo.mRole)
   379	    {
   380	    case OT_DEVICE_ROLE_CHILD:
   381	    case OT_DEVICE_ROLE_ROUTER:
