   420	        mParent.SetDeviceMode(ModeTlv::kModeFullThreadDevice | ModeTlv::kModeRxOnWhenIdle |
   421	                              ModeTlv::kModeFullNetworkData | ModeTlv::kModeSecureDataRequest);
   422	        mParent.SetRloc16(GetRloc16(GetRouterId(networkInfo.mRloc16)));
   423	        mParent.SetState(Neighbor::kStateRestored);
